/// Markdown config families that get outline/folding/link navigation:
/// `skill`, `claude_md`, `agent` (all `.md` surfaces in scan.rs's classify).
/// Everything else — including unknown `.md` like README.md — returns no
/// navigation.
fn is_markdown_config_doc(uri: &str) -> bool {
    matches!(crate::scan::classify(uri), "skill" | "claude_md" | "agent")
}

/// Extract the on-disk directory of a `file://` document URI, minimally
/// percent-decoded (`%20` -> space). Non-file URIs yield an empty string,
/// which document_links treats as "no resolvable targets" (a relative token
/// against "" produces a URI that cannot be a real path — links still parse,
/// so callers wanting file-only links should keep the markdown-only gate).
fn doc_dir_from_uri(uri: &str) -> String {
    let Some(rest) = uri.strip_prefix("file://") else {
        return String::new();
    };
    let dir = rest.rsplit('/').nth(1).map(|_| {
        // Strip the last path component (the file name).
        match rest.rfind('/') {
            Some(idx) => &rest[..idx],
            None => rest,
        }
    });
    dir.unwrap_or("").replace("%20", " ")
}

#[cfg(test)]
mod andon_diagnostic_tests {
    use super::*;

    /// lsp-max 26.7.1's `Client::publish_diagnostics` auto-injects a synthetic
    /// `LSPMAX-ANDON-PUSH-MISSING` diagnostic whenever a batch contains an
    /// ERROR-severity diagnostic whose `source` isn't `"lsp-max-andon"`
    /// (see ~/lsp-max/src/service/client/lsp_methods.rs). This project's own
    /// findings are always emitted at WARNING severity today
    /// (`make_finding_with_source`), so the injection never fires in
    /// practice. This test pins that behavior down: if severity mapping is
    /// ever changed to honor `ccc:diagSeverity "error"` from the ontology,
    /// this test breaks as a deliberate signal to re-run the ANDON-injection
    /// verification described in docs/v26.7.3-PRD-ARD.md before shipping.
    #[test]
    fn findings_never_emit_error_severity_today() {
        let (_max, diag) = make_finding_with_source(
            "CCC-TEST-001",
            "test message",
            "json",
            "claude-code-config-lsp",
            Range::default(),
        );
        assert_ne!(
            diag.severity,
            Some(DiagnosticSeverity::ERROR),
            "a finding now emits ERROR severity — this will trigger lsp-max's \
             LSPMAX-ANDON-PUSH-MISSING auto-diagnostic on every publish unless \
             `source` is set to \"lsp-max-andon\" (it should not be spoofed) or \
             a real ANDON push is wired for this code path"
        );
    }

    #[test]
    fn scoped_findings_never_emit_error_severity_today() {
        for scope in [AgentScope::Project, AgentScope::Global, AgentScope::Plugin] {
            let (_max, diag) = ClaudeCodeConfigBackend::make_finding_scoped(
                "CCC-TEST-002",
                "test message",
                "claude_md",
                scope,
                Range::default(),
            );
            assert_ne!(diag.severity, Some(DiagnosticSeverity::ERROR));
        }
    }

    #[test]
    fn span_to_range_converts_byte_offsets_to_line_and_utf16_column() {
        let content = "line0\nline1 \u{1F600} rest";
        // "rest" starts after "line1 😀 " — 😀 is 2 UTF-16 code units, 4 UTF-8 bytes.
        let byte_offset = content.find("rest").unwrap();
        let range = span_to_range(content, (byte_offset, byte_offset + 4));
        assert_eq!(range.start.line, 1);
        assert_eq!(range.end.line, 1);
        // "line1 " (6 chars) + surrogate pair (2 code units) + " " (1) = 9.
        assert_eq!(range.start.character, 9);
        assert_ne!(
            range,
            Range::default(),
            "a non-zero span must not collapse to 0:0"
        );
    }

    #[test]
    fn zero_span_still_yields_default_range() {
        // The sentinel some validators use when they have no real offset
        // (validate_settings_json_enums parses through serde_json::Value).
        assert_eq!(span_to_range("anything", (0, 0)), Range::default());
    }

    // Found via dogfooding: settings.local.json didn't match
    // ends_with("settings.json"), so it silently skipped both
    // classification and enum validation entirely.
    #[test]
    fn settings_local_json_classifies_as_json() {
        assert_eq!(
            crate::scan::classify("file:///proj/.claude/settings.local.json"),
            "json"
        );
    }

    #[test]
    fn settings_json_still_classifies_as_json() {
        assert_eq!(
            crate::scan::classify("file:///proj/.claude/settings.json"),
            "json"
        );
    }
}
